item.stdout:
plugins {
    id 'java'
    id 'org.springframework.boot' version '3.5.16'
}

group = 'com.example'
version = '0.1.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    implementation platform('org.springframework.boot:spring-boot-dependencies:3.5.16')
    implementation 'org.springframework.boot:spring-boot-starter-web'
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    implementation 'org.springframework.boot:spring-boot-starter-jdbc'
    implementation 'org.springframework.boot:spring-boot-starter-actuator'
    runtimeOnly 'com.mysql:mysql-connector-j'
    runtimeOnly 'com.h2database:h2'
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

tasks.named('test') {
    useJUnitPlatform()
}

tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
}

tasks.named('bootJar') {
    archiveFileName = 'app.jar'
}

tasks.named('jar') {
    enabled = false
}
rootProject.name = 'gitcangku1'
org.gradle.caching=true
org.gradle.jvmargs=-Xmx1g -Dfile.encoding=UTF-8
org.gradle.daemon=false
spring:
  application:
    name: gitcangku1
  config:
    import: "optional:configtree:/run/secrets/"
  datasource:
    url: ${DB_URL:jdbc:h2:mem:local_demo;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1}
    username: ${DB_USER:sa}
    driver-class-name: ${DB_DRIVER:org.h2.Driver}
    hikari:
      maximum-pool-size: 5
      minimum-idle: 1
      connection-timeout: 10000
      validation-timeout: 3000
  sql:
    init:
      mode: ${SQL_INIT_MODE:always}
  jackson:
    time-zone: Asia/Shanghai
  lifecycle:
    timeout-per-shutdown-phase: 20s

server:
  port: 8080
  shutdown: graceful
  error:
    include-message: never
    include-stacktrace: never

management:
  endpoints:
    web:
      exposure:
        include: health
  endpoint:
    health:
      show-details: never
-- 澶氳绉嶆钀戒慨璁笌鍙戝竷蹇収 schema锛圚2 MySQL 鍏煎妯″紡锛夈€?-- 鎵€鏈夋椂闂村瓧娈典负鏁版嵁搴撻粯璁ゆ椂鍖烘椂闂存埑锛涚増鏈彿鍧囦粠 1锛堟枃妗ｅ彂甯冪増鏈粠 0锛夊紑濮嬪崟璋冮€掑銆?
CREATE TABLE IF NOT EXISTS document (
    document_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    target_languages VARCHAR(255) NOT NULL,
    draft_version INT NOT NULL,
    published_version INT NOT NULL,
    term_version INT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE document IS '鏂囨。锛氬叏灞€鍞竴 documentId锛屽惈 1~5 绉嶇洰鏍囪瑷€鍙婅崏绋?鍙戝竷/鏈鐗堟湰';
COMMENT ON COLUMN document.document_id IS '鍏ㄥ眬鍞竴鏂囨。 ID锛岃嚜澧?;
COMMENT ON COLUMN document.target_languages IS '鐩爣璇█鍒楄〃锛岄€楀彿鍒嗛殧鐨勫皬鍐欒瑷€鐮侊紝1~5 绉?;
COMMENT ON COLUMN document.draft_version IS '鏂囨。鑽夌鐗堟湰锛屼粠 1 寮€濮嬶紱澧炴钀芥垨淇敼婧愭枃/璇戞枃/鏈鏃跺姞涓€';
COMMENT ON COLUMN document.published_version IS '宸插彂甯冪増鏈彿锛屼粠 0 寮€濮嬶紝姣忔鎴愬姛鍙戝竷鍔犱竴';
COMMENT ON COLUMN document.term_version IS '褰撳墠鏈鐗堟湰锛屼粠 0 寮€濮嬶紙0 琛ㄧず灏氭湭寤虹珛鏈鐗堟湰锛夛紝姣忔鏂板鏈鐗堟湰鍔犱竴';
COMMENT ON COLUMN document.created_at IS '鍒涘缓鏃堕棿锛屾暟鎹簱榛樿鏃跺尯';

CREATE TABLE IF NOT EXISTS segment (
    document_id BIGINT NOT NULL,
    segment_id VARCHAR(64) NOT NULL,
    source_text LONGTEXT NOT NULL,
    source_version INT NOT NULL,
    PRIMARY KEY (document_id, segment_id)
);
COMMENT ON TABLE segment IS '娈佃惤锛氭枃妗ｅ唴鍞竴 segmentId锛屽惈婧愭枃鍙婃簮鏂囩増鏈?;
COMMENT ON COLUMN segment.document_id IS '鎵€灞炴枃妗?ID';
COMMENT ON COLUMN segment.segment_id IS '鏂囨。鍐呭敮涓€娈佃惤 ID';
COMMENT ON COLUMN segment.source_text IS '婧愭枃姝ｆ枃锛孶TF-8';
COMMENT ON COLUMN segment.source_version IS '婧愭枃鐗堟湰锛屼粠 1 寮€濮嬶紝姣忔婧愭枃淇鍔犱竴';

CREATE TABLE IF NOT EXISTS translation (
    document_id BIGINT NOT NULL,
    segment_id VARCHAR(64) NOT NULL,
    language VARCHAR(16) NOT NULL,
    content LONGTEXT NOT NULL,
    author VARCHAR(128) NOT NULL,
    source_version INT NOT NULL,
    translation_version INT NOT NULL,
    term_version INT NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (document_id, segment_id, language)
);
COMMENT ON TABLE translation IS '璇戞枃锛氭寜娈佃惤涓庤瑷€鍞竴锛屼繚瀛樻鏂囥€佷綔鑰呫€佹墍渚濇嵁婧愭枃鐗堟湰銆佺粦瀹氭湳璇増鏈強閫掑璇戞枃鐗堟湰';
COMMENT ON COLUMN translation.document_id IS '鎵€灞炴枃妗?ID';
COMMENT ON COLUMN translation.segment_id IS '鎵€灞炴钀?ID';
COMMENT ON COLUMN translation.language IS '鐩爣璇█鐮侊紝灏忓啓';
COMMENT ON COLUMN translation.content IS '璇戞枃姝ｆ枃锛孶TF-8';
COMMENT ON COLUMN translation.author IS '璇戞枃浣滆€咃紝鍙栨彁浜ゆ椂 X-Actor-Id';
COMMENT ON COLUMN translation.source_version IS '璇戞枃鎵€渚濇嵁鐨勬簮鏂囩増鏈紱鎻愪氦鏃跺繀椤荤瓑浜庡綋鍓嶆簮鏂囩増鏈?;
COMMENT ON COLUMN translation.translation_version IS '璇戞枃鐗堟湰锛屼粠 1 寮€濮嬶紝姣忔閲嶆柊鎻愪氦鍔犱竴';
COMMENT ON COLUMN translation.term_version IS '璇戞枃鎻愪氦鏃剁粦瀹氱殑鏈鐗堟湰锛涗笉绛変簬褰撳墠鏈鐗堟湰鏃惰涓烘湳璇繃鏈?;
COMMENT ON COLUMN translation.updated_at IS '鏈€杩戞彁浜ゆ椂闂达紝鏁版嵁搴撻粯璁ゆ椂鍖?;

CREATE TABLE IF NOT EXISTS approval (
    document_id BIGINT NOT NULL,
    segment_id VARCHAR(64) NOT NULL,
    language VARCHAR(16) NOT NULL,
    reviewer VARCHAR(128) NOT NULL,
    source_version INT NOT NULL,
    translation_version INT NOT NULL,
    approved_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (document_id, segment_id, language)
);
COMMENT ON TABLE approval IS '鎵瑰噯锛氭寜娈佃惤涓庤瑷€鍞竴锛涙簮鏂囨垨璇戞枃鐗堟湰鏀瑰彉鍚庡厛鍓嶆壒鍑嗕笉鍐嶆湁鏁?;
COMMENT ON COLUMN approval.document_id IS '鎵€灞炴枃妗?ID';
COMMENT ON COLUMN approval.segment_id IS '鎵€灞炴钀?ID';
COMMENT ON COLUMN approval.language IS '鐩爣璇█鐮侊紝灏忓啓';
COMMENT ON COLUMN approval.reviewer IS '瀹℃牳浜猴紝鍙栨壒鍑嗘椂 X-Actor-Id锛屼笉寰楁槸璇戞枃浣滆€?;
COMMENT ON COLUMN approval.source_version IS '鎵瑰噯鏃剁殑婧愭枃鐗堟湰锛屽彂甯冩牎楠岄』绛変簬褰撳墠婧愭枃鐗堟湰';
COMMENT ON COLUMN approval.translation_version IS '鎵瑰噯鏃剁殑璇戞枃鐗堟湰锛屽彂甯冩牎楠岄』绛変簬褰撳墠璇戞枃鐗堟湰';
COMMENT ON COLUMN approval.approved_at IS '鎵瑰噯鏃堕棿锛屾暟鎹簱榛樿鏃跺尯';

CREATE TABLE IF NOT EXISTS release_snapshot (
    document_id BIGINT NOT NULL,
    published_version INT NOT NULL,
    snapshot_json LONGTEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (document_id, published_version)
);
COMMENT ON TABLE release_snapshot IS '鍙戝竷蹇収锛氬彂甯冩椂鍘熷瓙鐢熸垚鐨勫畬鏁村彧璇诲揩鐓э紝JSON 搴忓垪鍖栵紝涓嶅彲淇敼';
COMMENT ON COLUMN release_snapshot.document_id IS '鎵€灞炴枃妗?ID';
COMMENT ON COLUMN release_snapshot.published_version IS '鍙戝竷鐗堟湰鍙凤紝浠?1 寮€濮?;
COMMENT ON COLUMN release_snapshot.snapshot_json IS '蹇収鍐呭 JSON锛氬叏閮ㄦ钀芥簮鏂囧強鍚勮瑷€璇戞枃銆佷綔鑰呫€佸鏍镐汉涓庣増鏈彿';
COMMENT ON COLUMN release_snapshot.created_at IS '鍙戝竷鏃堕棿锛屾暟鎹簱榛樿鏃跺尯';

CREATE TABLE IF NOT EXISTS term_version (
    document_id BIGINT NOT NULL,
    term_version INT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (document_id, term_version)
);
COMMENT ON TABLE term_version IS '鏈鐗堟湰锛氭瘡涓枃妗ｄ粠 1 寮€濮嬬殑涓嶅彲鍙樻湳璇揩鐓х増鏈紝宸叉湁鐗堟湰涓嶅彲瑕嗙洊';
COMMENT ON COLUMN term_version.document_id IS '鎵€灞炴枃妗?ID';
COMMENT ON COLUMN term_version.term_version IS '鏈鐗堟湰鍙凤紝浠?1 寮€濮嬪崟璋冮€掑';
COMMENT ON COLUMN term_version.created_at IS '鐗堟湰鍒涘缓鏃堕棿锛屾暟鎹簱榛樿鏃跺尯';

CREATE TABLE IF NOT EXISTS term_rule (
    document_id BIGINT NOT NULL,
    term_version INT NOT NULL,
    source_term VARCHAR(512) NOT NULL,
    language VARCHAR(16) NOT NULL,
    required_translation VARCHAR(2048) NOT NULL,
    PRIMARY KEY (document_id, term_version, source_term, language)
);
COMMENT ON TABLE term_rule IS '鏈瑙勫垯锛氬睘浜庢煇鏈鐗堟湰鐨勪笉鍙彉瑙勫垯锛屾寜 sourceTerm 涓庣洰鏍囪瑷€鍞竴锛屾瘡鐗堟湰 0~100 鏉?;
COMMENT ON COLUMN term_rule.document_id IS '鎵€灞炴枃妗?ID';
COMMENT ON COLUMN term_rule.term_version IS '鎵€灞炴湳璇増鏈彿';
COMMENT ON COLUMN term_rule.source_term IS '婧愭枃鏈锛孶nicode 鍘熸枃銆佸尯鍒嗗ぇ灏忓啓锛屾寜杩炵画瀛愪覆鍖归厤';
COMMENT ON COLUMN term_rule.language IS '鐩爣璇█鐮侊紝灏忓啓';
COMMENT ON COLUMN term_rule.required_translation IS '璇ユ湳璇湪鐩爣璇█涓殑蹇呰瘧鏂囨湰锛岄潪绌?;

CREATE TABLE IF NOT EXISTS request_log (
    request_id VARCHAR(128) PRIMARY KEY,
    request_hash VARCHAR(64) NOT NULL,
    response_status INT NOT NULL,
    response_body LONGTEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE request_log IS '鍐欐搷浣滃箓绛夊幓閲嶏細鍏ㄥ眬鍞竴 requestId锛屼粎璁板綍鎴愬姛缁撴灉锛屼笌涓氬姟鍙樻洿鍘熷瓙鎻愪氦';
COMMENT ON COLUMN request_log.request_id IS '鍏ㄥ眬鍞竴璇锋眰 ID';
COMMENT ON COLUMN request_log.request_hash IS '璇锋眰鍙傛暟瑙勮寖鍖栧悗鐨?SHA-256 鎽樿锛涘悓閿紓鍙傝繑鍥?409';
COMMENT ON COLUMN request_log.response_status IS '鍘熸垚鍔熷搷搴旂殑 HTTP 鐘舵€佺爜锛岀敤浜庨噸鏀?;
COMMENT ON COLUMN request_log.response_body IS '鍘熸垚鍔熷搷搴斾綋 JSON锛岀敤浜庨噸鏀?;
COMMENT ON COLUMN request_log.created_at IS '璁板綍鏃堕棿锛屾暟鎹簱榛樿鏃跺尯';
