        assertThat(byAuthor.status()).isEqualTo(422);

        ApiResult wrongVersion = approve(docId, "s1", "en", "bob", 7, newRequestId());
        assertThat(wrongVersion.status()).isEqualTo(422);

        ApiResult ok = approve(docId, "s1", "en", "bob", 1, newRequestId());
