    void publishAndQuerySnapshot() throws Exception {
        long docId = createDocument(newRequestId(), "[\"en\",\"ja\"]",
                "[{\"segmentId\":\"s1\",\"sourceText\":\"你好\"},{\"segmentId\":\"s2\",\"sourceText\":\"世界\"}]");
